// Package packs holds the emoji styles, sticker packs and animated emoji that ship inside the server binary.
//
// The assets are generated by `make emoji/build` (scripts/emoji/build.mjs) into the assets/ folder next to this
// file and embedded with go:embed, so a server on an air-gapped network needs nothing from the internet. Nothing
// here is stored in the database; the admin's switches for built-in packs are (models.PackState).
package packs

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"sync"
)

//go:embed assets
var embedded embed.FS

// manifest is assets/manifest.json as the build script writes it.
type manifest struct {
	Schema       int              `json:"schema"`
	EmojiStyles  []manifestStyle  `json:"emoji_styles"`
	StickerPacks []manifestPack   `json:"sticker_packs"`
	Animated     []AnimatedEmoji  `json:"animated_emoji"`
}

type manifestStyle struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	License      string `json:"license"`
	LicenseFile  string `json:"license_file"`
	Attribution  string `json:"attribution"`
	Source       string `json:"source"`
	SourceCommit string `json:"source_commit"`
	CellSize     int    `json:"cell_size"`
	Width        int    `json:"width"`
	Height       int    `json:"height"`
	Count        int    `json:"count"`
	Sheet        string `json:"sheet"`
	Index        string `json:"index"`
}

type manifestPack struct {
	ID           string    `json:"id"`
	Name         string    `json:"name"`
	Order        int       `json:"order"`
	Animated     bool      `json:"animated"`
	License      string    `json:"license"`
	LicenseFile  string    `json:"license_file"`
	Attribution  string    `json:"attribution"`
	Source       string    `json:"source"`
	SourceCommit string    `json:"source_commit"`
	Items        []Sticker `json:"items"`
}

// Style is one built-in emoji style: a WebP sprite sheet of CellSize px cells plus a JSON index that maps a code
// point sequence ("1f600", "1f44d-1f3fd") to the cell's top-left corner.
type Style struct {
	ID           string
	Name         string
	License      string
	LicenseFile  string
	Attribution  string
	Source       string
	SourceCommit string
	CellSize     int
	Width        int
	Height       int
	// Count is how many emoji the sheet covers; the clients fall back to the device font for the rest.
	Count     int
	SheetPath string
	IndexPath string
	// Version identifies the sheet and index bytes (a content hash). It is part of the asset URLs, which are
	// therefore immutable and can be cached forever.
	Version    string
	SheetBytes int64
	IndexBytes int64
}

// Sticker is one image of a built-in sticker pack.
type Sticker struct {
	ID       string `json:"id"`
	Name     string `json:"name"`
	Emoji    string `json:"emoji"`
	File     string `json:"file"`
	Animated bool   `json:"animated"`
	Bytes    int64  `json:"bytes"`
}

// StickerPack is a built-in sticker pack.
type StickerPack struct {
	ID           string
	Name         string
	Order        int
	Animated     bool
	License      string
	LicenseFile  string
	Attribution  string
	Source       string
	SourceCommit string
	Items        []Sticker
	// Version is a content hash of the pack's images; it is part of the asset URLs.
	Version string
	byID    map[string]*Sticker
}

// Item finds a sticker of the pack by id.
func (p *StickerPack) Item(id string) (*Sticker, bool) {
	s, ok := p.byID[id]
	return s, ok
}

// AnimatedEmoji maps a code point sequence to the animation (a Cove Moves sticker) shown for a message that
// consists of that single emoji.
type AnimatedEmoji struct {
	// Sequence is lower-case hex code points joined by "-", with every FE0F removed ("2764", "1f44d").
	Sequence string `json:"sequence"`
	// ID is the sticker id in the cove-moves pack.
	ID string `json:"id"`
}

// Catalog is the parsed set of built-in assets.
type Catalog struct {
	fsys     fs.FS
	Styles   []*Style
	Packs    []*StickerPack
	Animated []AnimatedEmoji
	// AnimatedVersion identifies the animated emoji table together with its images.
	AnimatedVersion string
	// AnimatedPackID is the sticker pack whose images back the animated emoji table.
	AnimatedPackID string
	styleByID      map[string]*Style
	packByID       map[string]*StickerPack
}

var (
	builtinOnce sync.Once
	builtin     *Catalog
	builtinErr  error
)

// Builtin returns the catalog embedded in the binary, parsed once.
func Builtin() (*Catalog, error) {
	builtinOnce.Do(func() {
		sub, err := fs.Sub(embedded, "assets")
		if err != nil {
			builtinErr = err
			return
		}
		builtin, builtinErr = Load(sub)
	})
	return builtin, builtinErr
}

// Load parses a catalog from an assets tree (the embedded one, or a test fixture).
func Load(fsys fs.FS) (*Catalog, error) {
	raw, err := fs.ReadFile(fsys, "manifest.json")
	if err != nil {
		return nil, fmt.Errorf("packs: read manifest: %w", err)
	}
	var m manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("packs: parse manifest: %w", err)
	}
	c := &Catalog{fsys: fsys, styleByID: map[string]*Style{}, packByID: map[string]*StickerPack{}, AnimatedPackID: "cove-moves"}

	for _, ms := range m.EmojiStyles {
		sheet, err := fs.ReadFile(fsys, ms.Sheet)
		if err != nil {
			return nil, fmt.Errorf("packs: style %s sheet: %w", ms.ID, err)
		}
		index, err := fs.ReadFile(fsys, ms.Index)
		if err != nil {
			return nil, fmt.Errorf("packs: style %s index: %w", ms.ID, err)
		}
		st := &Style{
			ID: ms.ID, Name: ms.Name, License: ms.License, LicenseFile: ms.LicenseFile, Attribution: ms.Attribution,
			Source: ms.Source, SourceCommit: ms.SourceCommit, CellSize: ms.CellSize, Width: ms.Width, Height: ms.Height,
			Count: ms.Count, SheetPath: ms.Sheet, IndexPath: ms.Index,
			Version: hashOf(sheet, index), SheetBytes: int64(len(sheet)), IndexBytes: int64(len(index)),
		}
		c.Styles = append(c.Styles, st)
		c.styleByID[st.ID] = st
	}

	for _, mp := range m.StickerPacks {
		p := &StickerPack{
			ID: mp.ID, Name: mp.Name, Order: mp.Order, Animated: mp.Animated, License: mp.License, LicenseFile: mp.LicenseFile,
			Attribution: mp.Attribution, Source: mp.Source, SourceCommit: mp.SourceCommit, Items: mp.Items,
			byID: map[string]*Sticker{},
		}
		h := sha256.New()
		for i := range p.Items {
			it := &p.Items[i]
			data, err := fs.ReadFile(fsys, it.File)
			if err != nil {
				return nil, fmt.Errorf("packs: pack %s item %s: %w", p.ID, it.ID, err)
			}
			it.Bytes = int64(len(data))
			h.Write([]byte(it.ID))
			h.Write(data)
			p.byID[it.ID] = it
		}
		p.Version = hex.EncodeToString(h.Sum(nil))[:12]
		c.Packs = append(c.Packs, p)
		c.packByID[p.ID] = p
	}

	c.Animated = m.Animated
	if moves := c.packByID[c.AnimatedPackID]; moves != nil {
		c.AnimatedVersion = moves.Version
	}
	for _, a := range c.Animated {
		if p := c.packByID[c.AnimatedPackID]; p == nil || p.byID[a.ID] == nil {
			return nil, fmt.Errorf("packs: animated emoji %s points at a missing animation %q", a.Sequence, a.ID)
		}
	}
	return c, nil
}

func hashOf(parts ...[]byte) string {
	h := sha256.New()
	for _, p := range parts {
		h.Write(p)
	}
	return hex.EncodeToString(h.Sum(nil))[:12]
}

// Style returns a built-in emoji style by id.
func (c *Catalog) Style(id string) (*Style, bool) {
	s, ok := c.styleByID[id]
	return s, ok
}

// Pack returns a built-in sticker pack by id.
func (c *Catalog) Pack(id string) (*StickerPack, bool) {
	p, ok := c.packByID[id]
	return p, ok
}

// File is an embedded asset ready to be served.
type File struct {
	io.ReadSeeker
	Size int64
	io   io.Closer
}

// Close releases the file.
func (f *File) Close() error { return f.io.Close() }

// Open opens an embedded asset by its manifest path.
func (c *Catalog) Open(path string) (*File, error) {
	f, err := c.fsys.Open(path)
	if err != nil {
		return nil, err
	}
	info, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, err
	}
	rs, ok := f.(io.ReadSeeker)
	if !ok {
		_ = f.Close()
		return nil, fmt.Errorf("packs: %s is not seekable", path)
	}
	return &File{ReadSeeker: rs, Size: info.Size(), io: f}, nil
}

// ReadFile reads an embedded asset (licence texts, small files).
func (c *Catalog) ReadFile(path string) ([]byte, error) { return fs.ReadFile(c.fsys, path) }
